/// `java.util.stream.Stream<E>`. Intermediate ops return a stream; `map` erases
/// the element to `Object` (its output type is not tracked); `collect` returns
/// a `null`-typed result that adopts the assignment context, like a diamond.
// An OBJECT stream's parallel toggles answer a stream of its own ELEMENT,
// which is what `BRet::Stream` reads. `BRet::SameStream` beside them reads
// the element as a PRIMITIVE kind and falls back to `IntStream` — right for
// the three primitive tables it was written for, and wrong here:
// `Stream<String> s = Stream.of("x").parallel();` was "IntStream cannot be
// converted to Stream<String>".
const STREAM_METHODS: &[BuiltinMethod] = &[
    // A stream is an `AutoCloseable`, which is the whole point of
    // `try (Stream<String> lines = Files.lines(path))` — the documented way to
    // read a file with a stream. Without `close()` the try-with-resources
    // desugaring had no method to call and the resource was "cannot find
    // symbol", about a declaration the program wrote correctly.
    bm("close", &[], BRet::Void, "()V"),
    bm(
        "onClose",
        &[BParam::Runnable],
        BRet::Stream,
        "(Ljava/lang/Runnable;)Ljava/util/stream/Stream;",
    ),
    // The parallel toggles. Every pipeline here runs on one thread, so these
    // change nothing about what a stream ANSWERS; `isParallel` reports what a
    // JDK would report, which is the only part a program can see.
    bm("isParallel", &[], BRet::Boolean, "()Z"),
    bm("parallel", &[], BRet::Stream, "()Ljava/util/stream/Stream;"),
    bm(
        "sequential",
        &[],
        BRet::Stream,
        "()Ljava/util/stream/Stream;",
    ),
    bm(
        "unordered",
        &[],
        BRet::Stream,
        "()Ljava/util/stream/Stream;",
    ),
    bm("getClass", &[], BRet::Class, "()Ljava/lang/Class;"),
    // A stream is an `Iterable`'s other half: `iterator()` is the terminal
    // that hands the pipeline over to a loop.
    bm("iterator", &[], BRet::Iterator, "()Ljava/util/Iterator;"),
    // A stream is an object: `toString`/`hashCode` are Object's and do NOT
    // consume the pipeline.
    bm("toString", &[], BRet::Str, "()Ljava/lang/String;"),
    bm("hashCode", &[], BRet::Int, "()I"),
    bm(
        "filter",
        &[BParam::Predicate],
        BRet::Stream,
        "(Ljava/util/function/Predicate;)Ljava/util/stream/Stream;",
    ),
    // `takeWhile`/`dropWhile` (Java 9): `takeWhile` STOPS at the first
    // element that fails, where `filter` keeps looking.
    bm(
        "takeWhile",
        &[BParam::Predicate],
        BRet::Stream,
        "(Ljava/util/function/Predicate;)Ljava/util/stream/Stream;",
    ),
    bm(
        "dropWhile",
        &[BParam::Predicate],
        BRet::Stream,
        "(Ljava/util/function/Predicate;)Ljava/util/stream/Stream;",
    ),
    bm(
        "map",
        &[BParam::UnaryOperator],
        BRet::StreamErased,
        "(Ljava/util/function/Function;)Ljava/util/stream/Stream;",
    ),
    bm(
        "mapToInt",
        &[BParam::UnaryOperator],
        BRet::IntStream,
        "(Ljava/util/function/ToIntFunction;)Ljava/util/stream/IntStream;",
    ),
    // The VM stores stream elements unboxed, so a `double`/`long` pipeline is
    // the same machinery as an int one; only the numeric terminals differ,
    // which the descriptor tells the VM.
    bm(
        "mapToDouble",
        &[BParam::UnaryOperator],
        BRet::DoubleStream,
        "(Ljava/util/function/ToDoubleFunction;)Ljava/util/stream/DoubleStream;",
    ),
    bm(
        "mapToLong",
        &[BParam::UnaryOperator],
        BRet::LongStream,
        "(Ljava/util/function/ToLongFunction;)Ljava/util/stream/LongStream;",
    ),
    // `flatMap(f)` — each element's own stream is spliced into this one.
    bm(
        "flatMap",
        &[BParam::UnaryOperator],
        BRet::StreamErased,
        "(Ljava/util/function/Function;)Ljava/util/stream/Stream;",
    ),
    // The primitive splices: the same function, into a primitive pipeline.
    // `Arrays.stream(grid).flatMapToInt(Arrays::stream)` is how a program sums
    // a grid, and the name was in no table at all.
    bm(
        "flatMapToInt",
        &[BParam::UnaryOperator],
        BRet::IntStream,
        "(Ljava/util/function/Function;)Ljava/util/stream/IntStream;",
    ),
    bm(
        "flatMapToLong",
        &[BParam::UnaryOperator],
        BRet::LongStream,
        "(Ljava/util/function/Function;)Ljava/util/stream/LongStream;",
    ),
    bm(
        "flatMapToDouble",
        &[BParam::UnaryOperator],
        BRet::DoubleStream,
        "(Ljava/util/function/Function;)Ljava/util/stream/DoubleStream;",
    ),
    // `reduce(identity, accumulator)` folds to a value of the identity's type;
    // the one-argument form answers an `Optional`.
    bm(
        "reduce",
        &[BParam::Elem, BParam::BiFunction],
        BRet::Elem,
        "(Ljava/lang/Object;Ljava/util/function/BinaryOperator;)Ljava/lang/Object;",
    ),
    bm(
        "reduce",
        &[BParam::BiFunction],
        BRet::Optional,
        "(Ljava/util/function/BinaryOperator;)Ljava/util/Optional;",
    ),
    // `reduce(identity, accumulator, combiner)` — the three-argument form a
    // parallel fold needs, where the accumulator and the combiner may differ.
    // On one thread the combiner is never called, which is what a JDK does for
    // a sequential stream too; it is evaluated and then not used, so a
    // combiner that throws does not.
    bm(
        "reduce",
        &[BParam::Object, BParam::BiFunction, BParam::BiFunction],
        BRet::Elem,
        "(Ljava/lang/Object;Ljava/util/function/BiFunction;Ljava/util/function/BinaryOperator;)Ljava/lang/Object;",
    ),
    bm("toArray", &[], BRet::ObjectArray, "()[Ljava/lang/Object;"),
    // `stream.toArray(String[]::new)`. A stream has NO `toArray(T[])` overload
    // in Java — only the generator one — so the desugaring renames the call to
    // this internal name, which a program cannot write. Spelling it `toArray`
    // here would have accepted `stream.toArray(new String[0])`, which javac
    // rejects.
    bm(
        "__toArrayTyped",
        &[BParam::RefArray],
        BRet::ObjectArray,
        "([Ljava/lang/Object;)[Ljava/lang/Object;",
    ),
    bm("sorted", &[], BRet::Stream, "()Ljava/util/stream/Stream;"),
    bm(
        "sorted",
        &[BParam::Comparator],
        BRet::Stream,
        "(Ljava/util/Comparator;)Ljava/util/stream/Stream;",
    ),
    bm("distinct", &[], BRet::Stream, "()Ljava/util/stream/Stream;"),
    bm(
        "limit",
        &[BParam::Long],
        BRet::Stream,
        "(J)Ljava/util/stream/Stream;",
    ),
    bm(
        "skip",
        &[BParam::Long],
        BRet::Stream,
        "(J)Ljava/util/stream/Stream;",
    ),
    bm(
        "peek",
        &[BParam::Consumer],
        BRet::Stream,
        "(Ljava/util/function/Consumer;)Ljava/util/stream/Stream;",
    ),
    bm(
        "forEach",
        &[BParam::Consumer],
        BRet::Void,
        "(Ljava/util/function/Consumer;)V",
    ),
    bm(
        "forEachOrdered",
        &[BParam::Consumer],
        BRet::Void,
        "(Ljava/util/function/Consumer;)V",
    ),
    bm("count", &[], BRet::Long, "()J"),
    bm(
        "anyMatch",
        &[BParam::Predicate],
        BRet::Boolean,
        "(Ljava/util/function/Predicate;)Z",
    ),
    bm(
        "allMatch",
        &[BParam::Predicate],
        BRet::Boolean,
        "(Ljava/util/function/Predicate;)Z",
    ),
    bm(
        "noneMatch",
        &[BParam::Predicate],
        BRet::Boolean,
        "(Ljava/util/function/Predicate;)Z",
    ),
    bm(
        "collect",
        &[BParam::Collector],
        BRet::Nullish,
        "(Ljava/util/stream/Collector;)Ljava/lang/Object;",
    ),
    // The THREE-argument form, which gathers without a `Collector` at all:
    // a supplier makes the container, an accumulator puts each element in,
    // and a combiner merges two — never called here, since one thread never
    // splits the work.
    bm(
        "collect",
        &[BParam::Supplier, BParam::BiConsumer, BParam::BiConsumer],
        BRet::Nullish,
        "(Ljava/util/function/Supplier;Ljava/util/function/BiConsumer;Ljava/util/function/BiConsumer;)Ljava/lang/Object;",
    ),
    bm("findFirst", &[], BRet::Optional, "()Ljava/util/Optional;"),
    bm("findAny", &[], BRet::Optional, "()Ljava/util/Optional;"),
    bm(
        "max",
        &[BParam::Comparator],
        BRet::Optional,
        "(Ljava/util/Comparator;)Ljava/util/Optional;",
    ),
    bm(
        "min",
        &[BParam::Comparator],
        BRet::Optional,
        "(Ljava/util/Comparator;)Ljava/util/Optional;",
    ),
];

/// `java.util.stream.IntStream` — a primitive int stream. Its lambdas take a
/// single `int` (the VM stores the elements unboxed, so the same erased
