/// `java.io.StringWriter` — a writer whose output a program reads back.
/// `java.io.Writer` — the abstract class, and so exactly the methods a
/// variable declared as one may call. A `PrintWriter`'s `println` family and a
/// `StringWriter`'s `toString` are each their own class's, and neither is
/// reachable through this face — which is what a JDK's compiler says too.
const WRITER_FACE_METHODS: &[BuiltinMethod] = &[
    bm("write", &[BParam::Str], BRet::Void, "(Ljava/lang/String;)V"),
    // `write(int)`, not `write(char)`: a JDK takes an int and writes its low
    // sixteen bits, so `w.write(65)` writes an `A`. Typed as a char, that call
    // was "int cannot be converted to char".
    bm("write", &[BParam::Int], BRet::Void, "(I)V"),
    // `write(char[])` and its range form. A `char[]` is what a `Reader.read`
    // fills, so it is the shape a copy loop has in hand; every writer here
    // lacked both, and a JDK's range complaint on this form carries NO message
    // where the `String` form's names start, end and length.
    bm("write", &[BParam::CharArray], BRet::Void, "([C)V"),
    bm(
        "write",
        &[BParam::CharArray, BParam::Int, BParam::Int],
        BRet::Void,
        "([CII)V",
    ),
    bm(
        "write",
        &[BParam::Str, BParam::Int, BParam::Int],
        BRet::Void,
        "(Ljava/lang/String;II)V",
    ),
    bm(
        "append",
        &[BParam::CharSeq],
        BRet::WriterFace,
        "(Ljava/lang/CharSequence;)Ljava/io/Writer;",
    ),
    // `append(cs, start, end)` — the range form every `Writer` has, and the
    // one shape of it that takes an END rather than a length.
    bm(
        "append",
        &[BParam::CharSeq, BParam::Int, BParam::Int],
        BRet::WriterFace,
        "(Ljava/lang/CharSequence;II)Ljava/io/Writer;",
    ),
    bm(
        "append",
        &[BParam::Char],
        BRet::WriterFace,
        "(C)Ljava/io/Writer;",
    ),
    bm(
        "append",
        &[BParam::CharSeq, BParam::Int, BParam::Int],
        BRet::WriterFace,
        "(Ljava/lang/CharSequence;II)Ljava/io/Writer;",
    ),
    bm("flush", &[], BRet::Void, "()V"),
    bm("close", &[], BRet::Void, "()V"),
    bm("getClass", &[], BRet::Class, "()Ljava/lang/Class;"),
    bm("toString", &[], BRet::Str, "()Ljava/lang/String;"),
    bm(
        "equals",
        &[BParam::Object],
        BRet::Boolean,
        "(Ljava/lang/Object;)Z",
    ),
    bm("hashCode", &[], BRet::Int, "()I"),
];

