/// Every throwable's methods, plus whatever a particular one adds. Written
/// as a macro because a subclass with extra methods (a
/// `PatternSyntaxException`) needs the shared list AND its own, and a static
/// slice cannot be concatenated at compile time.
macro_rules! throwable_methods {
    // Every throwable's `getCause()` answers a `Throwable` — except the ones
    // that OVERRIDE it covariantly. `UncheckedIOException` declares
    // `IOException getCause()`, so `IOException c = e.getCause()` is ordinary
    // Java, and the shared entry refused it; it has to be the FIRST entry of
    // that name, since the first one that fits is the one chosen.
    ($($extra:expr,)*) => {
        throwable_methods!(cause = BRet::Throwable, "()Ljava/lang/Throwable;"; $($extra,)*)
    };
    (cause = $cause:expr, $cause_descriptor:expr; $($extra:expr,)*) => {
        &[
        bm("getClass", &[], BRet::Class, "()Ljava/lang/Class;"),
        // Every object has one; a throwable's is `Object`'s identity hash.
        bm("hashCode", &[], BRet::Int, "()I"),
        bm(
            "getStackTrace",
            &[],
            BRet::StackFrameArray,
            "()[Ljava/lang/StackTraceElement;",
        ),
        // `e.getClass()` — every object has it, and a validator reporting which
        // exception it caught needs it.
        BuiltinMethod {
            name: "getClass",
            params: &[],
            ret: BRet::Class,
            descriptor: "()Ljava/lang/Class;",
            needs: TableFace::Sorted,
        },
        BuiltinMethod {
            name: "getMessage",
            params: &[],
            ret: BRet::Str,
            descriptor: "()Ljava/lang/String;",
            needs: TableFace::Sorted,
        },
        BuiltinMethod {
            name: "toString",
            params: &[],
            ret: BRet::Str,
            descriptor: "()Ljava/lang/String;",
            needs: TableFace::Sorted,
        },
        BuiltinMethod {
            name: "printStackTrace",
            params: &[],
            ret: BRet::Void,
            descriptor: "()V",
            needs: TableFace::Sorted,
        },
        BuiltinMethod {
            name: "getLocalizedMessage",
            params: &[],
            ret: BRet::Str,
            descriptor: "()Ljava/lang/String;",
            needs: TableFace::Sorted,
        },
        // `getCause()` — the chained cause, or null.
        BuiltinMethod {
            name: "getCause",
            params: &[],
            ret: $cause,
            descriptor: $cause_descriptor,
            needs: TableFace::Sorted,
        },
        // `getSuppressed()` — the real suppressed exceptions, typed as `Object[]`
        // because `ElemType` has no exception variant, so `.length` and iteration
        // work while an element needs a cast to reach `getMessage()`.
        BuiltinMethod {
            name: "getSuppressed",
            params: &[],
            ret: BRet::ThrowableArray,
            descriptor: "()[Ljava/lang/Throwable;",
            needs: TableFace::Sorted,
        },
        // `addSuppressed(t)` — used by the try-with-resources desugaring, and
        // available to programs that manage suppression themselves.
        BuiltinMethod {
            name: "addSuppressed",
            params: &[BParam::Throwable],
            ret: BRet::Void,
            descriptor: "(Ljava/lang/Throwable;)V",
            needs: TableFace::Sorted,
        },
        // `fillInStackTrace()` re-records the trace AT THE CALL and returns
        // `this`, so a throwable rethrown elsewhere can be made to point at the
        // rethrow rather than its construction.
        BuiltinMethod {
            name: "fillInStackTrace",
            params: &[],
            ret: BRet::Throwable,
            descriptor: "()Ljava/lang/Throwable;",
            needs: TableFace::Sorted,
        },
        // `setStackTrace(frames)` REPLACES the recorded trace. A JDK copies
        // the array, so a caller that goes on mutating its own does not reach
        // inside the throwable.
        BuiltinMethod {
            name: "setStackTrace",
            params: &[BParam::StackFrameArray],
            ret: BRet::Void,
            descriptor: "([Ljava/lang/StackTraceElement;)V",
            needs: TableFace::Sorted,
        },
        // `initCause(t)` sets the cause and returns `this` (for chaining).
        BuiltinMethod {
            name: "initCause",
            params: &[BParam::Throwable],
            ret: BRet::Throwable,
            descriptor: "(Ljava/lang/Throwable;)Ljava/lang/Throwable;",
            needs: TableFace::Sorted,
        },
            $($extra,)*
        ]
    };
}

