/// Which empty collection a `Collections.emptyX()` call produces — the one
/// case where a `null`-typed receiver is really an object with methods.
#[derive(Clone, Copy)]
enum EmptyKind {
    List,
    Set,
    Map,
}

fn empty_collection_kind(receiver: &Expr) -> Option<EmptyKind> {
    let Expr::Call {
        receiver: Some(owner),
        method,
        args,
        ..
    } = receiver
    else {
        return None;
    };
    if !args.is_empty()
        || !matches!(owner.as_ref(), Expr::Name { path, .. } if path.last().is_some_and(|n| n == "Collections"))
    {
        return None;
    }
    match method.as_str() {
        "emptyList" => Some(EmptyKind::List),
        "emptySet" => Some(EmptyKind::Set),
        "emptyMap" => Some(EmptyKind::Map),
        _ => None,
    }
}

/// A `collect(...)` whose ELEMENT is unknown — the stream passed through a
/// `map`, which erases it — types as `null` so it still assigns to a
/// collection of any element. It is a real collection though, so a method
/// called straight on one resolves against the general face, exactly as
/// `Collections.emptyList()` does: without this,
/// `xs.stream().map(f).collect(toList()).size()` was "cannot call methods on
/// null" for something that printed perfectly.
fn collected_collection_kind(receiver: &Expr) -> Option<EmptyKind> {
    let Expr::Call { method, args, .. } = receiver else {
        return None;
    };
    if method != "collect" {
        return None;
    }
    let Some(Expr::Call {
        receiver: Some(owner),
        method: collector,
        ..
    }) = args.first()
    else {
        return None;
    };
    if !matches!(owner.as_ref(), Expr::Name { path, .. }
        if path.last().is_some_and(|name| name == "Collectors"))
    {
        return None;
    }
    match collector.as_str() {
        "toList" | "toUnmodifiableList" => Some(EmptyKind::List),
        "toSet" | "toUnmodifiableSet" => Some(EmptyKind::Set),
        "toMap" | "toUnmodifiableMap" | "groupingBy" | "partitioningBy" => Some(EmptyKind::Map),
        _ => None,
    }
}

/// `Optional.empty()` as a RECEIVER. It types as `null` so it assigns to an
/// `Optional` of any element (`Optional<String> o = Optional.empty()`), but it
/// is a real empty Optional, so a method called straight on one — javac infers
/// `Optional<Object>` there — has to resolve against the general face.
///
/// `Optional.ofNullable(null)` is the same object written another way, and
/// types the same, so it needs the same treatment: `ofNullable(null).orElse(d)`
/// is ordinary Java, and reporting "cannot call methods on null" about it
/// describes caturra's representation rather than the program.
/// `Stream.empty()` as a RECEIVER — the same shape as `Optional.empty()` and
/// for the same reason: it types as `null` so it can be a `Stream<String>`
/// wherever one is wanted, and a method called straight on one still has to
/// resolve against the general face.
fn is_empty_stream(receiver: &Expr) -> bool {
    matches!(
        receiver,
        Expr::Call {
            receiver: Some(owner),
            method,
            args,
            ..
        } if method == "empty"
            && args.is_empty()
            && matches!(owner.as_ref(), Expr::Name { path, .. }
                if path.last().is_some_and(|name| name == "Stream"))
    )
}

fn is_empty_optional(receiver: &Expr) -> bool {
    let Expr::Call {
        receiver: Some(owner),
        method,
        args,
        ..
    } = receiver
    else {
        return false;
    };
    let names_optional = matches!(owner.as_ref(), Expr::Name { path, .. }
        if path.last().is_some_and(|name| name == "Optional"));
    if !names_optional {
        return false;
    }
    match (method.as_str(), args.as_slice()) {
        ("empty", []) => true,
        ("ofNullable", [only]) => matches!(
            only,
            Expr::Literal {
                value: Literal::Null,
                ..
            }
        ),
        _ => false,
    }
}

/// Whether caturra models this type's `toString` text. The three I/O types
/// whose JDK text is a dump of internal state do not: a `Scanner`'s lists its
/// delimiters, position and locale separators. Concatenating one is refused
/// for the same reason, and the two refusals have to agree — a program that
/// cannot write `"" + scanner` must not be able to write `scanner.toString()`
/// and get an invented answer.
fn renders_as_text(ty: JType) -> bool {
    // A reader, a writer and a print stream have no text of their OWN: a JDK
    // gives each `Object`'s default, which is a class name and an address, and
    // caturra can spell that exactly. They were refused with the Scanner, back
    // when caturra could not.
    //
    // A `Scanner` is still refused, and is the reason this rule exists: its
    // text is a dump of the delimiters, the position and six locale
    // separators — real state, three bits of which caturra does not model, so
    // the choice there is an honest refusal or a confident wrong answer.
    !matches!(ty, JType::Scanner)
}

/// Whether a library type is modelled as ONE class — no interface/concrete
/// pair for a cast or an `instanceof` to choose between, and a class the VM
/// names its objects by. Both the cast rule and `instanceof` ask this, so the
/// two answer the same question: a checkcast to a name the VM does not know
/// throws, and accepting one here would turn a refusal into a wrong answer.
fn is_single_class_library_type(ty: JType) -> bool {
    matches!(
        ty,
        JType::Scanner
            | JType::File
            | JType::Writer(_)
            | JType::PrintStream
            | JType::ByteStream
            | JType::LocalDate
            | JType::LocalTime
            | JType::LocalDateTime
            | JType::Duration
            | JType::Period
            | JType::ChronoUnit
            | JType::ChronoField
            | JType::TemporalAdjuster
            | JType::IsoEra
            | JType::TemporalQuery
            | JType::Chronology
            | JType::TextStyle
            | JType::FormatStyle
            | JType::Year
            | JType::YearMonth
            | JType::MonthDay
            | JType::ValueRange
            | JType::DateFormat
            | JType::DayOfWeek
            | JType::Month
            | JType::Reader(_)
            | JType::Path
            | JType::Charset
            | JType::BigInteger
            | JType::BigDecimal
            | JType::RoundingMode
            | JType::MathContext
            | JType::DecimalFormat
            | JType::NumberFormat
            | JType::ParsePosition
            | JType::FieldPosition
            | JType::StringTokenizer
            | JType::Uuid
            | JType::Base64Encoder
            | JType::Base64Decoder
            | JType::BitSet
            | JType::StringWriter
            | JType::BufferedWriter
            | JType::WriterFace
            | JType::Pattern
            | JType::Matcher
            | JType::MatchResult
            | JType::Class
            | JType::StackFrame
            | JType::SummaryStats(_)
            // The three PRIMITIVE optionals — each a final class, like the
            // object `Optional` the list above reaches by name. Missing, the
            // cast an erased `Object` needs fell through to the UNBOXING arm
            // and `Function<OptionalInt, …> f = x -> 1` was "Object cannot be
            // converted to OptionalInt": a lambda could not take one at all.
            | JType::OptionalInt
            | JType::OptionalLong
            | JType::OptionalDouble
            // ...and the three REFLECTIVE values, also final classes. (A
            // `java.lang.reflect.Type` is an INTERFACE and stays out.)
            | JType::Field
            | JType::Method
            | JType::Constructor
    )
}

/// The intrinsic method table and JVM class for a receiver type.
#[allow(clippy::too_many_lines)] // one row per library type
fn builtin_instance_table(ty: JType) -> Option<(&'static str, &'static [BuiltinMethod])> {
    match ty {
        JType::Str => Some(("java/lang/String", STRING_METHODS)),
        JType::StringBuilder(kind) => Some((kind.internal(), STRINGBUILDER_METHODS)),
        JType::Class => Some(("java/lang/Class", CLASS_METHODS)),
        JType::Field => Some(("java/lang/reflect/Field", FIELD_METHODS)),
        JType::Method => Some(("java/lang/reflect/Method", METHOD_METHODS)),
        JType::StackFrame => Some(("java/lang/StackTraceElement", STACK_FRAME_METHODS)),
        JType::Type => Some(("java/lang/reflect/Type", TYPE_METHODS)),
        JType::Constructor => Some(("java/lang/reflect/Constructor", CONSTRUCTOR_METHODS)),
        JType::Scanner => Some(("java/util/Scanner", SCANNER_METHODS)),
        JType::File => Some(("java/io/File", FILE_METHODS)),
        // A `PatternSyntaxException` reports what was wrong with the pattern,
        // and that is three methods no other throwable has.
        JType::Exception(id)
            if exception_internal(id) == "java/util/regex/PatternSyntaxException" =>
        {
            Some((
                "java/util/regex/PatternSyntaxException",
                PATTERN_SYNTAX_METHODS,
            ))
        }
        JType::Exception(id)
            if let Some(methods) = detail_exception_methods(exception_internal(id)) =>
        {
            Some((exception_internal(id), methods))
        }
        // Three throwables name their CAUSE something else — each predates
        // `getCause` and kept the accessor it shipped with.
        JType::Exception(id)
            if matches!(
                exception_internal(id),
                "java/lang/ClassNotFoundException" | "java/lang/ExceptionInInitializerError"
            ) =>
        {
            Some((exception_internal(id), WRAPPED_CAUSE_METHODS))
        }
        JType::Exception(id)
            if exception_internal(id) == "java/lang/reflect/InvocationTargetException" =>
        {
            Some((
                "java/lang/reflect/InvocationTargetException",
                TARGET_EXCEPTION_METHODS,
            ))
        }
        JType::Exception(id) => Some((exception_internal(id), EXCEPTION_METHODS)),
        JType::Writer(kind) => Some((
            kind.internal(),
            match kind {
                WriterKind::Print => WRITER_METHODS,
                WriterKind::File => FILE_WRITER_METHODS,
            },
        )),
        JType::PrintStream => Some(("java/io/PrintStream", PRINT_STREAM_METHODS)),
        JType::LocalDate => Some(("java/time/LocalDate", LOCAL_DATE_METHODS)),
        JType::LocalTime => Some(("java/time/LocalTime", LOCAL_TIME_METHODS)),
        JType::Duration => Some(("java/time/Duration", DURATION_METHODS)),
        JType::Period => Some(("java/time/Period", PERIOD_METHODS)),
        JType::ChronoUnit => Some(("java/time/temporal/ChronoUnit", CHRONO_UNIT_METHODS)),
        JType::ChronoField => Some(("java/time/temporal/ChronoField", CHRONO_FIELD_METHODS)),
        JType::TemporalAdjuster => Some((
            "java/time/temporal/TemporalAdjuster",
            TEMPORAL_ADJUSTER_METHODS,
        )),
        JType::Chronology => Some(("java/time/chrono/IsoChronology", CHRONOLOGY_METHODS)),
        JType::IsoEra => Some(("java/time/chrono/IsoEra", ISO_ERA_METHODS)),
        JType::TextStyle => Some(("java/time/format/TextStyle", TEXT_STYLE_METHODS)),
        JType::FormatStyle => Some(("java/time/format/FormatStyle", STYLE_METHODS)),
        JType::Year => Some(("java/time/Year", YEAR_METHODS)),
        JType::YearMonth => Some(("java/time/YearMonth", YEAR_MONTH_METHODS)),
        JType::MonthDay => Some(("java/time/MonthDay", MONTH_DAY_METHODS)),
        JType::ValueRange => Some(("java/time/temporal/ValueRange", VALUE_RANGE_METHODS)),
        JType::DateFormat => Some(("java/time/format/DateTimeFormatter", DATE_FORMAT_METHODS)),
        JType::LocalDateTime => Some(("java/time/LocalDateTime", LOCAL_DATE_TIME_METHODS)),
        JType::DayOfWeek => Some(("java/time/DayOfWeek", DAY_OF_WEEK_METHODS)),
        JType::Month => Some(("java/time/Month", MONTH_METHODS)),
        JType::ByteStream => Some(("java/io/ByteArrayOutputStream", BYTE_STREAM_METHODS)),
        JType::Reader(face) => Some((
            face.internal(),
            match face {
                ReaderFace::Buffered => BUFFERED_READER_METHODS,
                // The two that decode BYTES, and so have a charset to name.
                ReaderFace::File | ReaderFace::InputStream => DECODING_READER_METHODS,
                ReaderFace::Abstract | ReaderFace::Stringy => READER_METHODS,
            },
        )),
        JType::Path => Some(("java/nio/file/Path", PATH_METHODS)),
        JType::BigInteger => Some(("java/math/BigInteger", BIG_INTEGER_METHODS)),
        JType::BigDecimal => Some(("java/math/BigDecimal", BIG_DECIMAL_METHODS)),
        JType::RoundingMode => Some(("java/math/RoundingMode", ROUNDING_MODE_METHODS)),
        JType::MathContext => Some(("java/math/MathContext", MATH_CONTEXT_METHODS)),
        JType::ParsePosition => Some(("java/text/ParsePosition", PARSE_POSITION_METHODS)),
        JType::FieldPosition => Some(("java/text/FieldPosition", FIELD_POSITION_METHODS)),
        JType::StringTokenizer => Some(("java/util/StringTokenizer", TOKENIZER_METHODS)),
        JType::Uuid => Some(("java/util/UUID", UUID_METHODS)),
        JType::Base64Encoder => Some(("java/util/Base64$Encoder", BASE64_ENCODER_METHODS)),
        JType::Base64Decoder => Some(("java/util/Base64$Decoder", BASE64_DECODER_METHODS)),
        JType::BitSet => Some(("java/util/BitSet", BITSET_METHODS)),
        JType::StringWriter => Some(("java/io/StringWriter", STRING_WRITER_METHODS)),
        JType::WriterFace => Some(("java/io/Writer", WRITER_FACE_METHODS)),
        JType::BufferedWriter => Some(("java/io/BufferedWriter", BUFFERED_WRITER_METHODS)),
        JType::DecimalFormat => Some(("java/text/DecimalFormat", DECIMAL_FORMAT_METHODS)),
        JType::NumberFormat => Some(("java/text/NumberFormat", NUMBER_FORMAT_METHODS)),
        JType::Charset => Some(("java/nio/charset/Charset", CHARSET_METHODS)),
        JType::Pattern => Some(("java/util/regex/Pattern", PATTERN_METHODS)),
        JType::Matcher => Some(("java/util/regex/Matcher", MATCHER_METHODS)),
        JType::MatchResult => Some(("java/util/regex/MatchResult", MATCH_RESULT_METHODS)),
        JType::List { .. } => Some(("java/util/ArrayList", LIST_METHODS)),
        JType::ListIterator(_) => Some(("java/util/ListIterator", LIST_ITERATOR_METHODS)),
        JType::CharSequence => Some(("java/lang/CharSequence", CHAR_SEQUENCE_METHODS)),
        JType::Stack(_) => Some(("java/util/Stack", STACK_METHODS)),
        // A `Vector` shares the `Stack` table under a narrower face, and a
        // `Hashtable` the `HashMap` table under a wider one.
        JType::Vector(_) => Some(("java/util/Vector", STACK_METHODS)),
        JType::Enumeration(_) => Some(("java/util/Enumeration", ENUMERATION_METHODS)),
        JType::Stream(_) => Some(("java/util/stream/Stream", STREAM_METHODS)),
        JType::IntStream => Some(("java/util/stream/IntStream", INTSTREAM_METHODS)),
        // A double/long pipeline shares the int surface; only the numeric
        // terminals differ, and `bret_type` substitutes those per receiver.
        // A `Collector` is a VALUE a program passes on: the only methods it
        // has are Object's. It needs a table of its own all the same, because
        // `OBJECT_METHODS` is mixed into every OTHER receiver's — a `toString`
        // added there would override the honest refusals that name it (a
        // `Scanner`'s text is one).
        JType::Collector(_) => Some(("java/util/stream/Collector", COLLECTOR_METHODS)),
        JType::SummaryStats(flavour) => Some((
            flavour.internal_name(),
            match flavour {
                SummaryFlavour::Int => SUMMARY_STATS_METHODS,
                SummaryFlavour::Long => LONG_SUMMARY_METHODS,
                SummaryFlavour::Double => DOUBLE_SUMMARY_METHODS,
            },
        )),
        JType::DoubleStream => Some(("java/util/stream/DoubleStream", INTSTREAM_METHODS)),
        JType::LongStream => Some(("java/util/stream/LongStream", INTSTREAM_METHODS)),
        JType::Iterator(_) => Some(("java/util/Iterator", ITERATOR_METHODS)),
        JType::EntryIterator { .. } => Some(("java/util/Iterator", ENTRY_ITERATOR_METHODS)),
        JType::Optional(_) => Some(("java/util/Optional", OPTIONAL_METHODS)),
        JType::OptionalInt => Some(("java/util/OptionalInt", OPTIONALINT_METHODS)),
        JType::OptionalDouble => Some(("java/util/OptionalDouble", OPTIONALDOUBLE_METHODS)),
        JType::OptionalLong => Some(("java/util/OptionalLong", OPTIONALLONG_METHODS)),
        JType::LinkedList { role, .. } => Some(match role {
            SeqRole::Full => ("java/util/LinkedList", LINKEDLIST_METHODS),
            SeqRole::ArrayDeque => ("java/util/ArrayDeque", DEQUE_METHODS),
            SeqRole::Queue => ("java/util/Queue", QUEUE_METHODS),
            SeqRole::Deque => ("java/util/Deque", DEQUE_METHODS),
        }),
        JType::Map { .. } => Some(("java/util/HashMap", MAP_METHODS)),
        JType::Hashtable { .. } => Some(("java/util/Hashtable", MAP_METHODS)),
        JType::TreeMap { .. } => Some(("java/util/TreeMap", TREEMAP_METHODS)),
        JType::Set { .. } => Some(("java/util/Set", SET_METHODS)),
        JType::TreeSet(_, role) => Some((role.set_internal(), TREESET_METHODS)),
        JType::Collection(_) => Some(("java/util/Collection", VIEW_METHODS)),
        JType::EntrySet { .. } => Some(("java/util/Set", ENTRY_SET_METHODS)),
        JType::MapEntry { .. } => Some(("java/util/Map$Entry", ENTRY_METHODS)),
        _ => None,
    }
}

