    /// `new File(pathString)`.
    fn new_file(&mut self, args: &[Expr], span: SourceSpan) -> JType {
        let file_class = intern_class(self.pool, "java/io/File");
        self.code.push_op_u16(op::NEW, file_class, 1);
        self.code.push_op(op::DUP, 1);
        if let [path] = args {
            let path_ty = self.expr(path);
            if path_ty == JType::Error {
                self.error_bail(span, "File path");
                return JType::Error;
            }
            if path_ty == JType::Str {
                let init_ref =
                    intern_method_ref(self.pool, "java/io/File", "<init>", "(Ljava/lang/String;)V");
                self.code.push_op_u16(op::INVOKESPECIAL, init_ref, 0);
                self.code.drop_stack(2);
                return JType::File;
            }
        }
        // `new File(directory, name)` — the form a program building a path out
        // of a listing writes, with the parent either a `File` or its path.
        if let [parent, child] = args {
            let parent_ty = self.expr(parent);
            let child_ty = self.expr(child);
            if parent_ty == JType::Error || child_ty == JType::Error {
                self.error_bail(span, "File path");
                return JType::Error;
            }
            let parent_desc = match parent_ty {
                JType::Str | JType::Null => Some("Ljava/lang/String;"),
                JType::File => Some("Ljava/io/File;"),
                _ => None,
            };
            if let Some(parent_desc) = parent_desc
                && child_ty == JType::Str
            {
                let init_ref = intern_method_ref(
                    self.pool,
                    "java/io/File",
                    "<init>",
                    &format!("({parent_desc}Ljava/lang/String;)V"),
                );
                self.code.push_op_u16(op::INVOKESPECIAL, init_ref, 0);
                self.code.drop_stack(3);
                return JType::File;
            }
        }
        self.error(
            span,
            "File takes a String path, or a parent and a name: new File(\"data.txt\"), new File(dir, \"data.txt\")",
        );
        JType::Error
    }

    /// `new BufferedWriter(writer)` — the writer it wraps, and optionally a
    /// buffer SIZE, which changes nothing a program can observe.
    fn new_buffered_writer(&mut self, args: &[Expr], span: SourceSpan) -> JType {
        let class = intern_class(self.pool, "java/io/BufferedWriter");
        self.code.push_op_u16(op::NEW, class, 1);
        self.code.push_op(op::DUP, 1);
        let ([target] | [target, _]) = args else {
            self.error(
                span,
                "BufferedWriter wraps a writer: new BufferedWriter(new FileWriter(path))",
            );
            return JType::Error;
        };
        let target_ty = self.expr(target);
        if target_ty == JType::Error {
            self.error_bail(span, "BufferedWriter target");
            return JType::Error;
        }
        if !matches!(
            target_ty,
            JType::Writer(_) | JType::StringWriter | JType::BufferedWriter | JType::WriterFace
        ) {
            self.error(
                span,
                format!(
                    "BufferedWriter wraps a Writer, not {}",
                    target_ty.describe(self.table)
                ),
            );
            return JType::Error;
        }
        // The size is evaluated for its own failure and dropped: the VM's
        // buffer grows as it needs to.
        if let [_, size] = args {
            let size_ty = self.expr(size);
            self.numeric_conversion(size_ty, JType::Int);
            self.code.push_op(op::POP, 0);
            self.code.drop_stack(1);
        }
        let init = intern_method_ref(
            self.pool,
            "java/io/BufferedWriter",
            "<init>",
            "(Ljava/io/Writer;)V",
        );
        self.code.push_op_u16(op::INVOKESPECIAL, init, 0);
        self.code.drop_stack(2);
        JType::BufferedWriter
    }

    /// `new PrintWriter(pathString)` or `new PrintWriter(fileExpr)`.
    fn new_writer(&mut self, class: &'static str, args: &[Expr], span: SourceSpan) -> JType {
        let writer_class = intern_class(self.pool, class);
        self.code.push_op_u16(op::NEW, writer_class, 1);
        self.code.push_op(op::DUP, 1);
        if let [target] | [target, _] = args {
            let target_ty = self.expr(target);
            if target_ty == JType::Error {
                self.error_bail(span, "writer target");
                return JType::Error;
            }
            // `new FileWriter(path, append)` — the second argument says
            // whether to keep what the file already holds.
            let appends = match args {
                [_, flag] => {
                    let flag_ty = self.expr(flag);
                    if flag_ty != JType::Boolean {
                        self.error(
                            span,
                            "the second argument of a FileWriter is the append flag",
                        );
                        return JType::Error;
                    }
                    true
                }
                _ => false,
            };
            let descriptor = match (target_ty, appends) {
                // A `PrintWriter` over a `StringWriter` writes into memory,
                // which is how a program builds text with `printf`.
                (JType::StringWriter | JType::WriterFace, false) => Some("(Ljava/io/Writer;)V"),
                (JType::Str, false) => Some("(Ljava/lang/String;)V"),
                (JType::Str, true) => Some("(Ljava/lang/String;Z)V"),
                (JType::File, false) => Some("(Ljava/io/File;)V"),
                (JType::File, true) => Some("(Ljava/io/File;Z)V"),
                _ => None,
            };
            if let Some(descriptor) = descriptor {
                let init_ref = intern_method_ref(self.pool, class, "<init>", descriptor);
                self.code.push_op_u16(op::INVOKESPECIAL, init_ref, 0);
                self.code.drop_stack(if appends { 3 } else { 2 });
                return JType::Writer(if class == "java/io/FileWriter" {
                    WriterKind::File
                } else {
                    WriterKind::Print
                });
            }
        }
        self.error(
            span,
            "PrintWriter takes a path or a File: new PrintWriter(\"out.txt\")",
        );
        JType::Error
    }

    /// `new ByteArrayOutputStream()` — an empty buffer. The `(int)` form
