    /// `new Vector<E>()`, `new Vector<>(capacity)`, or the copy constructor.
    /// The storage is a `Stack`'s; only the class it names and the face it
    /// shows differ.
    fn new_vector(&mut self, type_args: &[TypeRef], args: &[Expr], span: SourceSpan) -> JType {
        let elem = match type_args {
            [] => None,
            [arg] => {
                let Some(elem) = elem_from_type_arg(arg, self.table) else {
                    self.error(
                        span,
                        "Vector element type must be Integer, Double, Boolean, \
                         Character, String, or a class",
                    );
                    return JType::Error;
                };
                Some(elem)
            }
            _ => {
                self.error(span, "Vector takes one type argument");
                return JType::Error;
            }
        };
        let class = intern_class(self.pool, "java/util/Vector");
        self.code.push_op_u16(op::NEW, class, 1);
        self.code.push_op(op::DUP, 1);
        // The capacity HINT and the copy constructor take one argument each,
        // and only the argument's type tells them apart.
        let descriptor = match args {
            [] => "()V",
            [only] => {
                let ty = self.expr(only);
                if ty == JType::Error {
                    self.error_bail(span, "Vector argument");
                    return JType::Error;
                }
                if matches!(ty, JType::Int | JType::Short | JType::Byte | JType::Char) {
                    "(I)V"
                } else {
                    "(Ljava/util/Collection;)V"
                }
            }
            // `new Vector<>(capacity, increment)` — the growth STEP, which is
            // what makes a `Vector`'s capacity different from an
            // `ArrayList`'s: a positive increment adds that many slots where
            // the default doubles. `capacity()` reports the difference.
            [capacity, increment] => {
                for argument in [capacity, increment] {
                    let ty = self.expr(argument);
                    self.numeric_conversion(ty, JType::Int);
                }
                "(II)V"
            }
            _ => {
                self.error(span, "Vector takes a capacity or a collection to copy");
                return JType::Error;
            }
        };
        let init = intern_method_ref(self.pool, "java/util/Vector", "<init>", descriptor);
        self.code.push_op_u16(op::INVOKESPECIAL, init, 0);
        self.code
            .drop_stack(1 + u16::try_from(args.len()).unwrap_or(0));
        let elem = elem.unwrap_or_else(|| self.diamond_elem());
        JType::Vector(elem)
    }

    /// `new HashMap<K, V>()`, `new HashMap<>(initialCapacity)`, or the copy
    /// constructor `new HashMap<>(otherMap)`.
    /// The static type of `new AbstractMap.SimpleEntry<…>` from its type
    /// arguments alone — `Null` (assignable to any `Map.Entry`) for a
    /// diamond, like the other diamond constructors in `type_of_new_object`.
    fn simple_entry_type(&mut self, type_args: &[TypeRef], args: &[Expr]) -> JType {
        if let [key, value] = type_args
            && let (Some(key), Some(value)) = (
                elem_from_type_arg(key, self.table),
                elem_from_type_arg(value, self.table),
            )
        {
            return JType::MapEntry { key, value };
        }
        // A DIAMOND takes its key and value from the ARGUMENTS, which is what
        // javac infers and what the emission path answers. Returning `Null`
        // here — an entry that adopts its context — disagreed with the emitter
        // about every `new AbstractMap.SimpleEntry<>(k, v)` in the suite.
        let object = ElemType::Object(self.table.object_id);
        let (key_ty, value_ty) = match args {
            [key, value] => (self.type_of(key), self.type_of(value)),
            _ => return JType::Null,
        };
        JType::MapEntry {
            key: collection_elem_of(key_ty).unwrap_or(object),
            value: collection_elem_of(value_ty).unwrap_or(object),
        }
    }

    /// `new AbstractMap.SimpleEntry<>(key, value)` — a standalone
    /// `Map.Entry`, modelled as an entry view over a hidden one-mapping map
    /// (so `getKey`/`getValue`/`setValue`/`toString` all flow through the
    /// existing entry machinery).
    /// `new AbstractMap.SimpleEntry<>(k, v)` and `Map.entry(k, v)`, which are
    /// one object with two promises: the first is mutable and takes a null,
    /// the second is one of the IMMUTABLE collections and takes neither.
    fn new_simple_entry(
        &mut self,
        type_args: &[TypeRef],
        args: &[Expr],
        span: SourceSpan,
        immutable: bool,
    ) -> JType {
        let declared = match type_args {
            [] => None,
            [key, value] => {
                if let (Some(key), Some(value)) = (
                    elem_from_type_arg(key, self.table),
                    elem_from_type_arg(value, self.table),
                ) {
                    Some((key, value))
                } else {
                    self.error(
                        span,
                        "AbstractMap.SimpleEntry key and value types must be Integer, \
                         Double, Boolean, Character, String, or a class",
                    );
                    return JType::Error;
                }
            }
            _ => {
                self.error(span, "AbstractMap.SimpleEntry takes two type arguments");
                return JType::Error;
            }
        };
        if args.len() != 2 {
            self.error(
                span,
                "AbstractMap.SimpleEntry takes a key and a value argument",
            );
            return JType::Error;
        }
        let key_ty = self.expr(&args[0]);
        if let Some(elem) = boxable_primitive(key_ty) {
            self.emit_box(elem);
        }
        let value_ty = self.expr(&args[1]);
        if let Some(elem) = boxable_primitive(value_ty) {
            self.emit_box(elem);
        }
        let method_ref = intern_method_ref(
            self.pool,
            "java/lang/System",
            if immutable {
                "__mapEntry"
            } else {
                "__simpleEntry"
            },
            "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",
        );
        self.code.push_op_u16(op::INVOKESTATIC, method_ref, 0);
        self.code.drop_stack(2);
        self.code.grow_stack(1);
        let (key, value) = declared.unwrap_or_else(|| {
            let object = ElemType::Object(self.table.object_id);
            (
                self.holdable_elem(key_ty).unwrap_or(object),
                self.holdable_elem(value_ty).unwrap_or(object),
            )
        });
        JType::MapEntry { key, value }
    }

    /// `new HashMap<>(...)` and `new LinkedHashMap<>(...)`. Both are a
    /// `Map` here — the only difference is the class constructed, which is what
    /// tells the VM to iterate in INSERTION order and what `getClass` reports.
    fn new_hash_map(
        &mut self,
        class: &'static str,
        type_args: &[TypeRef],
        args: &[Expr],
        span: SourceSpan,
    ) -> JType {
        if args.len() > 1 {
            self.error(span, "HashMap takes at most one constructor argument");
            return JType::Error;
        }
        let mut entry = match type_args {
            // Diamond `new HashMap<>()`: the key and value types come from
            // the assignment context (or the copy source below).
            [] => None,
            [key, value] => {
                let key = elem_from_type_arg(key, self.table);
                let value = elem_from_type_arg(value, self.table);
                let (Some(key), Some(value)) = (key, value) else {
                    self.error(
                        span,
                        "HashMap key and value types must be Integer, Double, Boolean, \
                         Character, String, or a class",
                    );
                    return JType::Error;
                };
                Some((key, value))
            }
            _ => {
                self.error(span, "HashMap takes two type arguments");
                return JType::Error;
            }
        };
        let map_class = intern_class(self.pool, class);
        self.code.push_op_u16(op::NEW, map_class, 1);
        self.code.push_op(op::DUP, 1);
        match args {
            [] => {
                let init_ref = intern_method_ref(self.pool, class, "<init>", "()V");
                self.code.push_op_u16(op::INVOKESPECIAL, init_ref, 0);
                self.code.drop_stack(1);
            }
            [source] => {
                let source_ty = self.expr(source);
                // `new HashMap<>(map)` copies; `new HashMap<>(16)` sizes. A
                // SORTED map is a Map too — `new HashMap<>(treeMap)` used to be
                // refused as neither.
                let descriptor = if let JType::Map { key, value, .. }
                | JType::TreeMap { key, value, .. }
                | JType::Hashtable { key, value } = source_ty
                {
                    if entry.is_none() {
                        entry = Some((key, value));
                    }
                    "(Ljava/util/Map;)V"
                } else if source_ty == JType::Class {
                    // `new EnumMap<>(Day.class)` — the key type, which caturra
                    // does not need (the ORDER is the keys' own either way).
                    // Evaluated all the same, so its own failure stands.
                    "(Ljava/lang/Class;)V"
                } else {
                    if !widens(source_ty, JType::Int, self.table) {
                        self.error(span, "new HashMap(...) takes a Map or an int capacity");
                    }
                    "(I)V"
                };
                let init_ref = intern_method_ref(self.pool, class, "<init>", descriptor);
                self.code.push_op_u16(op::INVOKESPECIAL, init_ref, 0);
                self.code.drop_stack(2); // the dup'd receiver + the argument
            }
            _ => unreachable!("arg count checked above"),
        }
        // The `new` makes the CLASS — and a `Hashtable` is its own type, not
        // a face of the hash map it shares a table with.
        let (key, value) = entry.unwrap_or_else(|| (self.diamond_elem(), self.diamond_elem()));
        if class == "java/util/Hashtable" {
            return JType::Hashtable { key, value };
        }
        JType::Map {
            key,
            value,
            face: CollFace::Concrete,
        }
    }

