                let source_ty = self.expr(source);
                if let Some(source_elem) = collection_element_type(source_ty, self.table) {
                    if elem.is_none() {
                        elem = Some(source_elem);
                    }
                } else if source_ty != JType::Null {
                    self.error(span, "new LinkedList(...) takes a Collection");
                }
